// core/movement.js — single velocity update for all entities
// Exponential lerp: fast approach, slow settle (matches current friction feel)
export function updateVelocity(e, dt) {
  // Horizontal: lerp vx toward vxGoal at e.accel rate
  e.vx += ((e.vxGoal ?? 0) - e.vx) * (e.accel ?? 10) * dt;
  // Snap to zero when close enough (avoid float dust)
  if (Math.abs(e.vx) < 1 && (e.vxGoal ?? 0) === 0) e.vx = 0;

  // Vertical: lerp vy toward vyGoal (gravity goal) at e.gravAccel rate
  e.vy += ((e.vyGoal ?? 0) - e.vy) * (e.gravAccel ?? 8) * dt;

  // Integrate position
  e.x += e.vx * dt;
  e.y += e.vy * dt;
}

// Impulse: set velocity directly (knockback, jump, explosion)
// The goal system will naturally decay it toward the next frame's goal.
export function applyImpulse(e, ivx, ivy) {
  e.vx += ivx;
  e.vy += ivy;
}

